refusal(report: Verification): string | undefined {
	const { stored } = this;
	if (stored === undefined || JSON.stringify(stored) === JSON.stringify(report)) return undefined;
	if (verdictStrength[report.verdict] > verdictStrength[stored.verdict]) return undefined;
	const lowered = stored.lowered === undefined ? "" : `, lowered ${stored.lowered.from} to ${stored.lowered.to}`;
	return `this claim is already judged ${stored.verdict}${lowered}, and a later report of it is taken only at a stronger verdict, so the first report stands with its reason`;
}

// Runs in the report's commit, so a refused report writes nothing, and a replay finds its own report stored.
const refusal = new VerificationRecord(previous).refusal(verification);
if (refusal !== undefined) throw new Error(refusal);
if (JSON.stringify(previous) === JSON.stringify(verification)) return;

const matches = dismissed.flatMap(({ id: from, dismissal }) => {
	const lifecycle = state.items[from]?.lifecycle;
	// A dismissal replaced since the verifier was shown it is not the one it judged.
	if (lifecycle === undefined || identityOf(lifecycle) !== dismissal) return [];
	const same = claims.every(
		(claim) =>
			state.items[claim.id]?.verifications?.[revision]?.[producerKey(claim.source)]?.[version]?.matches?.[
				from
			] === "same",
	);
	if (!same) return [];
	// The highest any lens reported, before a verifier lowered it: a stored sighting keeps the lens's own.
	const reported = claims
		// Every claim judged the same has a record, and so a sighting.
		.map((claim) => sightingIn(state, revision, claim.id, claim.source)!.properties.severity)
		.reduce<Severity>(stricter, "nit");
	// Only a dismissal with a recorded severity is a root.
	const fenced = severityRank[reported] < severityRank[lifecycle.dismissedSeverity!];
	const kind: Inheritance["kind"] = fenced || claims.some(floored) ? "proposed" : "inherited";
	// A dismissal records its time beside its severity.
	return [{ from, kind, at: lifecycle.dismissedAt! }];

 * The record after `report` arrives. The stronger verdict wins whole. On equal verdicts the record keeps the higher
 * severity, with the reason and evidence of the report that gave it, so a later equal report never weakens a stored
 * one, in either order. Sameness answers are the latest report's, since each one answers every dismissed finding.
 */
after(report: Verification): Verification {
	const kept = this.#stronger(report);
	return report.matches === undefined ? kept : { ...kept, matches: report.matches };
}
